-- c028-v002: dan lihatlah gempa terjadi besar malaikat karena Tuhan turun dari surga dan datang menggulingkan – batu dan duduk di–atas nya
-- c028-v003: adalah dan – penampilan nya seperti kilat dan – pakaian nya putih seperti salju
-- c028-v004: dari dan – ketakutan dia gemetar – yang–menjaga dan menjadi seperti orang–mati
-- c028-v005: menjawab dan – malaikat berkata kepada– perempuan Jangan takut kamu aku–tahu karena bahwa Yesus – yang–disalibkan kamu–mencari
-- c028-v006: tidak Dia–ada di–sini Dia–dibangkitkan karena seperti Dia–katakan marilah lihatlah – tempat di–mana Dia–berbaring
-- c028-v007: dan cepat pergilah katakanlah kepada– murid–murid Nya bahwa Dia–dibangkitkan dari – orang–mati dan lihatlah Dia–mendahului kamu ke – Galilea di–sana Dia kamu–akan–melihat lihatlah aku–berkata kepadamu
-- c028-v008: dan pergi cepat dari – kubur dengan takut dan sukacita besar mereka–berlari memberitakan kepada– murid–murid Nya
-- c028-v009: Ketika dan mereka–pergi memberitakan kepada– murid–murid Nya dan lihatlah Yesus menemui mereka berkata Salam – dan datang mereka–memegang Nya – kaki dan menyembah Dia
-- c028-v010: kemudian berkata kepada–mereka – Yesus Jangan takut pergilah beritakanlah kepada– saudara–saudara Ku supaya mereka–pergi ke – Galilea dan–di–sana Aku mereka–akan–melihat
-- c028-v011: Pergi dan mereka lihatlah beberapa – penjaga datang ke – kota memberitahukan kepada– imam–imam–kepala semua – yang–terjadi
-- c028-v012: dan berkumpul dengan – tua–tua keputusan dan mengambil perak cukup–banyak mereka–memberi kepada– prajurit
-- c028-v013: berkata Katakanlah bahwa – Murid–murid Nya malam datang mencuri Dia kami sedang–tidur
-- c028-v014: dan jika terdengar ini kepada – gubernur kami akan–membujuk dia dan kamu tanpa–khawatir akan–membuat
-- c028-v015: – dan mengambil – perak mereka–melakukan seperti mereka–diajarkan Dan tersebar – perkataan ini di–antara orang–Yahudi sampai – hari–ini hari
-- c028-v016: – Dan sebelas murid pergi ke – Galilea ke – gunung di–mana menentukan mereka – Yesus
-- c028-v017: dan melihat Dia mereka–menyembah – tetapi mereka–ragu
-- c028-v018: dan datang – Yesus berbicara kepada–mereka berkata Diberikan kepada–Ku semua kuasa di surga dan di–atas – bumi
